#include <iostream>
#include <string>
#include <string_view>

class GradeBook {
public:
    // Mutator function to store course name
    void setCourseName(std::string_view name) {
        courseName = name;
    }

    // Accessor function marked const as it does not modify object state
    std::string getCourseName() const {
        return courseName;
    }

    // Display function calls getCourseName() to promote loose coupling
    void displayMessage() const {
        std::cout << "Welcome to the grade book for\n"
                  << getCourseName() << "!\n";
    }

private:
    std::string courseName; // Default-initialized to empty string
};

int main() {
    GradeBook myGradeBook;

    // Display initial value (empty string)
    std::cout << "Initial course name is: " << myGradeBook.getCourseName() << "\n";

    // Set new course name from input
    std::string nameOfCourse;
    if (std::getline(std::cin, nameOfCourse)) {
        myGradeBook.setCourseName(nameOfCourse);
    }

    std::cout << "\n";
    myGradeBook.displayMessage();

    return 0;
}
